   347→            </div>
   348→            <div className="pipeline-arrow">→</div>
   349→            <div className="pipeline-step">
   350→              <h4>Clip</h4>
   351→              <p>Constrain to viewport</p>
   352→            </div>
   353→            <div className="pipeline-arrow">→</div>
   354→            <div className="pipeline-step">
   355→              <h4>Rasterize</h4>
   356→              <p>Edges to pixels</p>
   357→            </div>
   358→            <div className="pipeline-arrow">→</div>
   359→            <div className="pipeline-step">
   360→              <h4>Shade</h4>
   361→              <p>Compute color</p>
   362→            </div>
   363→            <div className="pipeline-arrow">→</div>
   364→            <div className="pipeline-step">
   365→              <h4>Blend</h4>
   366→              <p>Composite layers</p>
   367→            </div>
   368→            <div className="pipeline-arrow">→</div>
   369→            <div className="pipeline-step">
   370→              <h4>Pixels</h4>
   371→              <p>Final framebuffer</p>
   372→            </div>
   373→          </div>
