            </div>
            <div className="pipeline-arrow">→</div>
            <div className="pipeline-step">
              <h4>MEM</h4>
              <p>Memory Access</p>
            </div>
            <div className="pipeline-arrow">→</div>
            <div className="pipeline-step">
              <h4>WB</h4>
              <p>Write Back</p>
            </div>
          </div>
        </section>

